using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools are discovered by the SDK via [McpServerToolType] on the class
/// and [McpServerTool] on each method. Constructor parameters are resolved from DI.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The SDK resolves constructor params from the DI container.
    // Because we register IHttpClientFactory and use a named client,
    // we inject HttpClient directly (the SDK calls IHttpClientFactory for us
    // when we register with .AddHttpClient in Program.cs).
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        // Example using Open-Meteo geocoding + forecast (free, no API key)
        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1",
            cancellationToken);

        if (geo?.Results is not [var location, ..])
            return $"Could not find location: {city}";

        var weather = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"https://api.open-meteo.com/v1/forecast?latitude={location.Latitude}&longitude={location.Longitude}&current_weather=true",
            cancellationToken);

        if (weather?.CurrentWeather is null)
            return "Weather data unavailable.";

        var w = weather.CurrentWeather;
        return $"Weather in {city}: {w.Temperature}°C, wind {w.WindSpeed} km/h";
    }

    [McpServerTool, Description("Get a 3-day forecast for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        CancellationToken cancellationToken = default)
    {
        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1",
            cancellationToken);

        if (geo?.Results is not [var location, ..])
            return $"Could not find location: {city}";

        var url = $"https://api.open-meteo.com/v1/forecast?latitude={location.Latitude}&longitude={location.Longitude}"
                + "&daily=temperature_2m_max,temperature_2m_min&forecast_days=3&timezone=auto";

        var forecast = await _httpClient.GetFromJsonAsync<ForecastResponse>(url, cancellationToken);
        if (forecast?.Daily is null)
            return "Forecast data unavailable.";

        var lines = forecast.Daily.Time.Select((date, i) =>
            $"  {date}: {forecast.Daily.TemperatureMin[i]}–{forecast.Daily.TemperatureMax[i]}°C");

        return $"3-day forecast for {city}:\n{string.Join("\n", lines)}";
    }
}

// --- JSON models for Open-Meteo API ---

