    [property: JsonPropertyName("temperature_2m_max")] double[] TemperatureMax,
    [property: JsonPropertyName("temperature_2m_min")] double[] TemperatureMin);

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    // Register a named HttpClient that gets injected into WeatherTools
    .AddHttpClient<WeatherTools>(client =>
    {
        client.DefaultRequestHeaders.Add("User-Agent", "McpWeatherServer/1.0");
    });

builder.Services
    .AddMcpServer()
    .WithStdioTransport()
    .WithToolsFromAssembly();  // Discovers all [McpServerToolType] classes

await builder.Build().RunAsync();

